using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json;

namespace ResearchAgent.Tools;

public static class WebSearchTool
{
    private static readonly HttpClient s_httpClient = new();

    [Description("Searches the web for information on a given query and returns relevant results.")]
    public static async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        // Use a web search API. This implementation uses a simple simulation
        // that can be swapped for a real search provider (Bing, Google, Brave, etc.)
        var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY");
        var searchEndpoint = Environment.GetEnvironmentVariable("SEARCH_ENDPOINT");

        if (!string.IsNullOrEmpty(searchApiKey) && !string.IsNullOrEmpty(searchEndpoint))
        {
            return await ExecuteRealSearchAsync(query, searchApiKey, searchEndpoint);
        }

        // Fallback: simulate search results for demonstration
        return $"""
            Search results for "{query}":
            1. [Wikipedia] {query} - Overview and history of the topic, covering key developments and notable figures in the field.
            2. [Research Paper] Recent advances in {query} - A 2025 survey paper discussing current state-of-the-art approaches and future directions.
            3. [News] Latest developments in {query} - Recent news coverage highlighting breakthroughs and industry applications.
            4. [Tutorial] Getting started with {query} - A comprehensive guide covering fundamentals, best practices, and common pitfalls.
            5. [Forum Discussion] Expert opinions on {query} - Community discussion with insights from practitioners and researchers.
            """;
    }

    private static async Task<string> ExecuteRealSearchAsync(
        string query, string apiKey, string endpoint)
    {
        using var request = new HttpRequestMessage(HttpMethod.Get,
            $"{endpoint}?q={Uri.EscapeDataString(query)}&count=5");
        request.Headers.Add("Ocp-Apim-Subscription-Key", apiKey);

        var response = await s_httpClient.SendAsync(request);
        response.EnsureSuccessStatusCode();

        var json = await response.Content.ReadAsStringAsync();
        using var doc = JsonDocument.Parse(json);

        var results = new List<string>();
        if (doc.RootElement.TryGetProperty("webPages", out var webPages) &&
            webPages.TryGetProperty("value", out var values))
        {
            foreach (var item in values.EnumerateArray().Take(5))
            {
                var name = item.GetProperty("name").GetString();
                var snippet = item.GetProperty("snippet").GetString();
                results.Add($"- {name}: {snippet}");
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : "No results found.";
    }
}

using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Takes a note to remember a key finding or piece of information during research.")]
    public string TakeNote(
        [Description("The content of the note to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
}

