using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class Notepad
{
    private readonly List<string> _notes = [];

    [Description("Takes a note to remember a key finding or piece of information during research.")]
    public string TakeNote(
        [Description("The content of the note to save")] string note)
    {
        _notes.Add(note);
        return $"Note saved ({_notes.Count} total notes).";
    }

    [Description("Retrieves all notes taken so far during the research session.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes taken yet.";

        return string.Join("\n", _notes.Select((n, i) => $"{i + 1}. {n}"));
    }

    public IReadOnlyList<string> GetAllNotes() => _notes.AsReadOnly();
}

