arguments.new_str:
using Microsoft.Extensions.AI;
using Microsoft.Agents.AI;
using ResearchAgent.Tools;

var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable to run this agent.");

const string modelId = "gpt-4o-mini-2024-07-18";

var openAIClient = new OpenAI.OpenAIClient(apiKey);
IChatClient chatClient = openAIClient.GetChatClient(modelId).AsIChatClient();

var notepad = new Notepad();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(WebSearchTool.SearchAsync),
    AIFunctionFactory.Create(notepad.TakeNote),
    AIFunctionFactory.Create(notepad.GetNotes),
};

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. Given a topic, search the web to gather information,
        take notes on key findings, then produce a concise summary of your research.
        Always search multiple times with different queries to get broad coverage,
        take notes on important points, then summarize your notes into a final answer.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics by searching the web and taking notes.",
    tools: tools);

Console.WriteLine("Research Agent Ready!");
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

using var session = await agent.CreateSessionAsync();

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    session);

foreach (var message in response.Messages.Where(m => m.Role == ChatRole.Assistant))
{
    if (!string.IsNullOrEmpty(message.Text))
    {
        Console.WriteLine(message.Text);
    }
}

Console.WriteLine("\n--- Notes Collected ---");
foreach (var note in notepad.GetAllNotes())
{
    Console.WriteLine($"• {note}");
}

